<?php require 'config/db.php';require 'includes/functions.php';require_login();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $patient=trim($_POST['patient_name']??'');$group=$_POST['blood_group']??'';$units=max(1,(int)($_POST['units']??1));$priority=$_POST['priority']??'urgent';$hospital=(int)($_POST['hospital_id']??0);$needed=$_POST['needed_by']??'';$reason=trim($_POST['reason']??'');$address=trim($_POST['address']??''); if(!$patient||!$group||!$needed||!$address){$error='Please complete all required fields.';}else{$h=$conn->query('SELECT * FROM hospitals WHERE id='.$hospital)->fetch_assoc();$lat=$h?(float)$h['lat']:23.8103;$lng=$h?(float)$h['lng']:90.4125;$st=$conn->prepare("INSERT INTO blood_requests(requester_id,hospital_id,patient_name,blood_group,units,priority,needed_by,reason,address,lat,lng,status,broadcast_radius) VALUES(?,?,?,?,?,?,?,?,?,?,?,'verified',3)");$uid=user()['id'];$st->bind_param('iississssdd',$uid,$hospital,$patient,$group,$units,$priority,$needed,$reason,$address,$lat,$lng);if($st->execute()){ $id=$conn->insert_id;create_matches($conn,$id);case_event($conn,$id,'Request created',$group.' / '.$priority);case_event($conn,$id,'Matching started','Compatible donor matching started');audit($conn,'Created blood request','blood_request',$id,$group.' / '.$priority);flash('success','Emergency request created. Compatible donor matching has started.');header('Location: request-view.php?id='.$id);exit;}else{$error='Could not create request.';}}}
$hosp=$conn->query('SELECT * FROM hospitals WHERE verified=1 ORDER BY name');$pageTitle='Request Blood';include 'includes/header.php';?>
<section class="page-hero"><div class="container"><span class="kicker">Emergency intake</span><h1>Create a blood request</h1><p>Enter the verified medical need. BloodNet will start with nearby compatible donors and create a trackable emergency case.</p></div></section><div class="container"><div class="form-shell" style="max-width:1100px"><div class="form-side"><span class="kicker" style="color:#fecdd3">Smart emergency mode</span><h2>One request becomes a coordinated case.</h2><p>After submission, the system checks compatible blood groups, ranks available donors, sends notifications and opens the live case timeline.</p><div class="login-demo"><b>Privacy rule</b><span>Donor phone numbers are never shown on the public request list.</span></div></div><div class="form-main"><h2>Patient & requirement</h2><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="form-row"><div class="form-group"><label>Patient name</label><input class="form-control" name="patient_name" required></div><div class="form-group"><label>Blood group</label><select class="form-control" name="blood_group"><?php foreach(['O-','O+','A-','A+','B-','B+','AB-','AB+'] as $g):?><option><?=$g?></option><?php endforeach;?></select></div></div><div class="form-row"><div class="form-group"><label>Units required</label><input class="form-control" type="number" name="units" min="1" max="10" value="1"></div><div class="form-group"><label>Priority</label><select class="form-control" name="priority"><option value="critical">Critical — immediate</option><option value="urgent" selected>Urgent</option><option value="normal">Normal</option></select></div></div><div class="form-row"><div class="form-group"><label>Hospital / blood bank</label><select class="form-control" name="hospital_id"><?php while($h=$hosp->fetch_assoc()):?><option value="<?=$h['id']?>"><?=e($h['name'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Needed by</label><input class="form-control" type="datetime-local" name="needed_by" value="<?=date('Y-m-d\TH:i',time()+14400)?>" required></div></div><div class="form-group"><label>Location / ward</label><input class="form-control" name="address" placeholder="Hospital, ward, city" required></div><div class="form-group"><label>Medical reason / note</label><textarea class="form-control" name="reason" rows="3" placeholder="e.g. emergency surgery"></textarea></div><button class="btn btn-primary btn-lg" style="width:100%"><i class="fa-solid fa-bolt"></i> Create & start matching</button></form></div></div></div>
